python -c 'from seating_planner.rules import Hardness, Rule, RuleType
r = Rule(id='''r1''', rule_type='''same_table''', hardness='''soft''', weight=80, guest_ids=('''g1''','''g2'''))
assert r.rule_type is RuleType.SAME_TABLE and r.hardness is Hardness.SOFT and r.weight == 80
assert Rule(id='''r2''', rule_type=RuleType.DIFFERENT_TABLE, hardness=Hardness.HARD, guest_ids=('''g1''','''g2''')).weight is None
for bad in (0, 101, -1, 3.5, '''50''', None, True):
    try:
        Rule(id='''rx''', rule_type='''same_table''', hardness='''soft''', weight=bad, guest_ids=('''g1''','''g2'''))
    except ValueError:
        pass
    else:
        raise SystemExit(f'''soft weight {bad!r} was accepted''')
try:
    Rule(id='''rx''', rule_type='''same_table''', hardness='''hard''', weight=50, guest_ids=('''g1''','''g2'''))
except ValueError:
    pass
else:
    raise SystemExit('''hard rule with weight was accepted''')
for kw in ({'''distance_m''': 3.0}, {'''min_zones''': 2}):
    Rule(id='''rx''', rule_type='''min_distance''', hardness='''hard''', **kw)
for kw in ({}, {'''distance_m''': 0.0}, {'''distance_m''': -1}, {'''min_zones''': 0}, {'''distance_m''': '''far apart'''}):
    try:
        Rule(id='''rx''', rule_type='''min_distance''', hardness='''hard''', **kw)
    except ValueError:
        pass
    else:
        raise SystemExit(f'''min_distance with {kw!r} was accepted''')
t = Rule.from_dict(r.to_dict())
assert t == r
assert Rule.from_dict(r.to_dict()).to_dict() == r.to_dict()'
